    {
      "symbol": "🚀",
      "tooltip": "A rocket is like a rapid ascent; it symbolizes accelerated progress and capabilities scaling."
    },
    {
      "symbol": "💡",
      "tooltip": "A lightbulb is like a new idea; it symbolizes innovation and the pursuit of knowledge."
    }
  ],
